= \'2XL\' THEN \'XXL\' WHEN S.SIZE = \'06XL\' THEN \'6XL\' WHEN S.SIZE = \'01XL\' THEN \'XL\' WHEN S.SIZE = \'46\' THEN \'6XL\' WHEN S.SIZE = \'44\' THEN \'5XL\' WHEN S.SIZE = \'42\' THEN \'4XL\' WHEN S.SIZE = \'40\' THEN \'3XL\' WHEN S.SIZE = \'38\' THEN \'XXL\' WHEN S.SIZE = \'36\' THEN \'XL\' WHEN S.SIZE = \'34\' THEN \'L\' WHEN S.SIZE = \'32\' THEN \'M\' WHEN S.SIZE = \'30\' THEN \'S\' WHEN S.SIZE = \'28\' THEN \'XS\' ELSE \'NO_MATCH\' END = I.SIZE AND S.ORDER_DATE > I.DATE AND S.ORDER_DATE <= LEAST(DATEADD(DAY, 15, I.DATE), CURRENT_DATE) GROUP BY I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE, I.INVENTORY ) SELECT MARKETPLACE_MAPPED, CATEGORY, BRANCH_CODE, SKU_GROUP, SIZE, SNAPSHOT_DATE AS DATE, OPENING_INVENTORY, LAST_15_DAYS_SALES, LEAST(LAST_15_DAYS_SALES, OPENING_INVENTORY) AS SALES_CONSIDERED FROM LAST30D_STR WHERE SNAPSHOT_DATE = CURRENT_DATE - 30 ORDER BY SNAPSHOT_DATE, BRANCH_CODE, SKU_GROUP, SIZE, MARKETPLACE_MAPPED ), last_45 AS ( WITH INVENTORY_UNPVT AS ( SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP) AS SKU_GROUP, NEW_CATEGORY AS CATEGORY, DATE, \'XS\' AS SIZE, XS_UNITS AS INVENTORY FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'S\', S_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'M\', M_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'L\', L_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XL\', XL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XXL\', XXL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'3XL\', XL3_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'4XL\', XL4_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'5XL\', XL5_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'6XL\', XL6_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 ), LAST45D_STR AS ( SELECT I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE AS SNAPSHOT_DATE, I.INVENTORY AS OPENING_INVENTORY, COALESCE(SUM(S.SHIPPING_QUANTITY), 0) AS LAST_15_DAYS_SALES FROM INVENTORY_UNPVT I LEFT JOIN snitch_db.maplemonk.Store_Fact_items_offline S ON S.BRANCH_CODE = I.BRANCH_CODE AND UPPER(S.SKU_GROUP) = I.SKU_GROUP AND CASE WHEN S.SIZE = \'XXXL\' THEN \'3XL\' WHEN S.SIZE = \'XXL\' THEN \'XXL\' WHEN S.SIZE = \'XS\' THEN \'XS\' WHEN S.SIZE = \'XL\' THEN \'XL\' WHEN S.SIZE = \'S\' THEN \'S\' WHEN S.SIZE = \'M\' THEN \'M\' WHEN S.SIZE = \'L\' THEN \'L\' WHEN S.SIZE = \'6XL\' THEN \'6XL\' WHEN S.SIZE = \'5XL\' THEN \'5XL\' WHEN S.SIZE = \'4XL\' THEN \'4XL\' WHEN S.SIZE = \'3XL\' THEN \'3XL\' WHEN S.SIZE = \'2XL\' THEN \'XXL\' WHEN S.SIZE = \'06XL\' THEN \'6XL\' WHEN S.SIZE = \'01XL\' THEN \'XL\' WHEN S.SIZE = \'46\' THEN \'6XL\' WHEN S.SIZE = \'44\' THEN \'5XL\' WHEN S.SIZE = \'42\' THEN \'4XL\' WHEN S.SIZE = \'40\' THEN \'3XL\' WHEN S.SIZE = \'38\' THEN \'XXL\' WHEN S.SIZE = \'36\' THEN \'XL\' WHEN S.SIZE = \'34\' THEN \'L\' WHEN S.SIZE = \'32\' THEN \'M\' WHEN S.SIZE = \'30\' THEN \'S\' WHEN S.SIZE = \'28\' THEN \'XS\' ELSE \'NO_MATCH\' END = I.SIZE AND S.ORDER_DATE > I.DATE AND S.ORDER_DATE <= LEAST(DATEADD(DAY, 15, I.DATE), CURRENT_DATE) GROUP BY I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE, I.INVENTORY ) SELECT MARKETPLACE_MAPPED, CATEGORY, BRANCH_CODE, SKU_GROUP, SIZE, SNAPSHOT_DATE AS DATE, OPENING_INVENTORY, LAST_15_DAYS_SALES, LEAST(LAST_15_DAYS_SALES, OPENING_INVENTORY) AS SALES_CONSIDERED FROM LAST45D_STR WHERE SNAPSHOT_DATE = CURRENT_DATE - 45 ORDER BY SNAPSHOT_DATE, BRANCH_CODE, SKU_GROUP, SIZE, MARKETPLACE_MAPPED ), last_60 AS ( WITH INVENTORY_UNPVT AS ( SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP) AS SKU_GROUP, NEW_CATEGORY AS CATEGORY, DATE, \'XS\' AS SIZE, XS_UNITS AS INVENTORY FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'S\', S_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'M\', M_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'L\', L_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XL\', XL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XXL\', XXL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'3XL\', XL3_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'4XL\', XL4_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'5XL\', XL5_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'6XL\', XL6_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 ), LAST60D_STR AS ( SELECT I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE AS SNAPSHOT_DATE, I.INVENTORY AS OPENING_INVENTORY, COALESCE(SUM(S.SHIPPING_QUANTITY), 0) AS LAST_15_DAYS_SALES FROM INVENTORY_UNPVT I LEFT JOIN snitch_db.maplemonk.Store_Fact_items_offline S ON S.BRANCH_CODE = I.BRANCH_CODE AND UPPER(S.SKU_GROUP) = I.SKU_GROUP AND CASE WHEN S.SIZE = \'XXXL\' THEN \'3XL\' WHEN S.SIZE = \'XXL\' THEN \'XXL\' WHEN S.SIZE = \'XS\' THEN \'XS\' WHEN S.SIZE = \'XL\' THEN \'XL\' WHEN S.SIZE = \'S\' THEN \'S\' WHEN S.SIZE = \'M\' THEN \'M\' WHEN S.SIZE = \'L\' THEN \'L\' WHEN S.SIZE = \'6XL\' THEN \'6XL\' WHEN S.SIZE = \'5XL\' THEN \'5XL\' WHEN S.SIZE = \'4XL\' THEN \'4XL\' WHEN S.SIZE = \'3XL\' THEN \'3XL\' WHEN S.SIZE = \'2XL\' THEN \'XXL\' WHEN S.SIZE = \'06XL\' THEN \'6XL\' WHEN S.SIZE = \'01XL\' THEN \'XL\' WHEN S.SIZE = \'46\' THEN \'6XL\' WHEN S.SIZE = \'44\' THEN \'5XL\' WHEN S.SIZE = \'42\' THEN \'4XL\' WHEN S.SIZE = \'40\' THEN \'3XL\' WHEN S.SIZE = \'38\' THEN \'XXL\' WHEN S.SIZE = \'36\' THEN \'XL\' WHEN S.SIZE = \'34\' THEN \'L\' WHEN S.SIZE = \'32\' THEN \'M\' WHEN S.SIZE = \'30\' THEN \'S\' WHEN S.SIZE = \'28\' THEN \'XS\' ELSE \'NO_MATCH\' END = I.SIZE AND S.ORDER_DATE > I.DATE AND S.ORDER_DATE <= LEAST(DATEADD(DAY, 15, I.DATE), CURRENT_DATE) GROUP BY I.MARKETPLACE_MAPPED, I.CATEGORY, I.BRANCH_CODE, I.SKU_GROUP, I.SIZE, I.DATE, I.INVENTORY ) SELECT MARKETPLACE_MAPPED, CATEGORY, BRANCH_CODE, SKU_GROUP, SIZE, SNAPSHOT_DATE AS DATE, OPENING_INVENTORY, LAST_15_DAYS_SALES, LEAST(LAST_15_DAYS_SALES, OPENING_INVENTORY) AS SALES_CONSIDERED FROM LAST60D_STR WHERE SNAPSHOT_DATE = CURRENT_DATE - 60 ORDER BY SNAPSHOT_DATE, BRANCH_CODE, SKU_GROUP, SIZE, MARKETPLACE_MAPPED ), today_inv AS ( WITH INVENTORY_UNPVT AS ( SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP) AS SKU_GROUP, NEW_CATEGORY AS CATEGORY, DATE, \'XS\' AS SIZE, XS_UNITS AS INVENTORY FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'S\', S_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'M\', M_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'L\', L_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XL\', XL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'XXL\', XXL_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'3XL\', XL3_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'4XL\', XL4_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'5XL\', XL5_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT MARKETPLACE_MAPPED, BRANCH_CODE, UPPER(SKU_GROUP), NEW_CATEGORY, DATE, \'6XL\', XL6_UNITS FROM snitch_db.maplemonk.offline_master_daily_report_1 ) SELECT MARKETPLACE_MAPPED, CATEGORY, BRANCH_CODE, SKU_GROUP, SIZE, DATE AS SNAPSHOT_DATE, INVENTORY AS CLOSING_INVENTORY_TODAY FROM INVENTORY_UNPVT WHERE DATE = CURRENT_DATE ) SELECT COALESCE( A.MARKETPLACE_MAPPED, B.MARKETPLACE_MAPPED, C.MARKETPLACE_MAPPED, D.MARKETPLACE_MAPPED, E.MARKETPLACE_MAPPED ) AS MARKETPLACE_MAPPED, COALESCE( A.CATEGORY, B.CATEGORY, C.CATEGORY, D.CATEGORY, E.CATEGORY ) AS CATEGORY, COALESCE(A.BRANCH_CODE, B.BRANCH_CODE, C.BRANCH_CODE, D.BRANCH_CODE, E.BRANCH_CODE) AS BRANCH_CODE, COALESCE(A.SKU_GROUP, B.SKU_GROUP, C.SKU_GROUP, D.SKU_GROUP, E.SKU_GROUP) AS SKU_GROUP, COALESCE(A.SIZE, B.SIZE, C.SIZE, D.SIZE, E.SIZE) AS SIZE, COALESCE(A.OPENING_INVENTORY, 0) AS OPENING_INVENTORY_L15D, COALESCE(B.OPENING_INVENTORY, 0) AS OPENING_INVENTORY_L30D, COALESCE(C.OPENING_INVENTORY, 0) AS OPENING_INVENTORY_L45D, COALESCE(D.OPENING_INVENTORY, 0) AS OPENING_INVENTORY_L60D, COALESCE(E.CLOSING_INVENTORY_TODAY, 0) AS CLOSING_INVENTORY_TODAY, COALESCE(A.LAST_15_DAYS_SALES, 0) AS SALES_D0_15, COALESCE(B.LAST_15_DAYS_SALES, 0) AS SALES_D15_30, COALESCE(C.LAST_15_DAYS_SALES, 0) AS SALES_D30_45, COALESCE(D.LAST_15_DAYS_SALES, 0) AS SALES_D45_60, COALESCE(A.SALES_CONSIDERED, 0) AS SALES_CONSIDERED_D0_15, COALESCE(B.SALES_CONSIDERED, 0) AS SALES_CONSIDERED_D15_30, COALESCE(C.SALES_CONSIDERED, 0) AS SALES_CONSIDERED_D30_45, COALESCE(D.SALES_CONSIDERED, 0) AS SALES_CONSIDERED_D45_60 FROM last_15 A FULL OUTER JOIN last_30 B ON A.BRANCH_CODE = B.BRANCH_CODE AND A.SKU_GROUP = B.SKU_GROUP AND A.SIZE = B.SIZE FULL OUTER JOIN last_45 C ON COALESCE(A.BRANCH_CODE, B.BRANCH_CODE) = C.BRANCH_CODE AND COALESCE(A.SKU_GROUP, B.SKU_GROUP) = C.SKU_GROUP AND COALESCE(A.SIZE, B.SIZE) = C.SIZE FULL OUTER JOIN last_60 D ON COALESCE(A.BRANCH_CODE, B.BRANCH_CODE, C.BRANCH_CODE) = D.BRANCH_CODE AND COALESCE(A.SKU_GROUP, B.SKU_GROUP, C.SKU_GROUP) = D.SKU_GROUP AND COALESCE(A.SIZE, B.SIZE, C.SIZE) = D.SIZE FULL OUTER JOIN today_inv E ON COALESCE(A.BRANCH_CODE, B.BRANCH_CODE, C.BRANCH_CODE, D.BRANCH_CODE) = E.BRANCH_CODE AND COALESCE(A.SKU_GROUP, B.SKU_GROUP, C.SKU_GROUP, D.SKU_GROUP) = E.SKU_GROUP AND COALESCE(A.SIZE, B.SIZE, C.SIZE, D.SIZE) = E.SIZE ) a LEFT JOIN ( SELECT * FROM ( SELECT Category AS product_type, sku_group, ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1 DESC) rn FROM snitch_db.maplemonk.metafields_data ) WHERE rn = 1 ) b ON LOWER(a.SKU_GROUP) = LOWER(b.sku_group) ) WHERE MARKETPLACE_MAPPED LIKE \'%COCO%\' OR MARKETPLACE_MAPPED LIKE \'%COFO%\' OR MARKETPLACE_MAPPED LIKE \'%FOCO%\'; create or replace table snitch_db.maplemonk.str_test_2 as WITH opening AS ( SELECT date AS opening_date, cluster, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, inventory AS opening_inventory, new_category, designs, collar_new, sleeve_type, fit, style FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date = current_date - 30 ), closing AS ( SELECT date AS closing_date, cluster, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, new_category, designs, collar_new, sleeve_type, fit, jit_qty, cut_size_with_jit_flag, num_size_available, style, fresh_inventory, FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date = current_date ), sales AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS sales_qty FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN current_date - 30 AND current_date AND marketplace_mapped NOT IN ( \'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA 2\',\'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\', \'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\', \'SNITCH - WH - NORTH\' ) AND doc_prefix NOT IN (\'QCOM\',\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), combined AS ( SELECT COALESCE(o.branch_code, c.branch_code, s.branch_code) AS branch_code, COALESCE(o.cluster, c.cluster) AS cluster, COALESCE(o.marketplace_mapped, c.marketplace_mapped, s.marketplace_mapped) AS marketplace_mapped, COALESCE(o.sku_group, c.sku_group, s.sku_group) AS sku_group, COALESCE(o.opening_inventory, 0) AS opening_inventory, COALESCE(c.closing_inventory, 0) AS closing_inventory, COALESCE(s.sales_qty, 0) AS sales_qty, ROUND( GREATEST( COALESCE(o.opening_inventory, 0) - COALESCE(s.sales_qty, 0) - COALESCE(c.closing_inventory, 0), 0 ), 2 ) AS outwards, COALESCE(o.new_category, c.new_category) AS new_category, COALESCE(o.designs, c.designs) AS designs, COALESCE(o.collar_new, c.collar_new) AS collar_new, COALESCE(o.sleeve_type, c.sleeve_type) AS sleeve_type, COALESCE(o.fit, c.fit) AS fit, COALESCE(o.style, c.style) AS style, COALESCE(c.jit_qty, 0) AS jit_qty, COALESCE(c.cut_size_with_jit_flag, \'No\') AS cut_size_with_jit_flag, c.num_size_available, c.fresh_inventory, FROM opening o FULL OUTER JOIN closing c ON o.branch_code = c.branch_code AND o.marketplace_mapped = c.marketplace_mapped AND o.sku_group = c.sku_group FULL OUTER JOIN sales s ON COALESCE(o.branch_code, c.branch_code) = s.branch_code AND COALESCE(o.marketplace_mapped, c.marketplace_mapped) = s.marketplace_mapped AND COALESCE(o.sku_group, c.sku_group) = s.sku_group ), filtered AS ( SELECT * FROM combined WHERE NOT ( opening_inventory = 0 AND closing_inventory = 0 AND sales_qty = 0 ) ), sku_store AS ( SELECT f.*, CASE WHEN (opening_inventory + closing_inventory) / 2.0 > 0 THEN ROUND( sales_qty / ((opening_inventory + closing_inventory) / 2.0), 2 ) ELSE 0 END AS sell_through_1, CASE WHEN (opening_inventory + closing_inventory) / 2.0 > 0 THEN ROUND( (sales_qty / ((opening_inventory + closing_inventory) / 2.0)) - (outwards / ((opening_inventory + closing_inventory) / 2.0)), 2 ) ELSE 0 END AS sell_through_2 FROM filtered f ), store_avg AS ( SELECT cluster, branch_code, marketplace_mapped, SUM(sales_qty) AS store_sales, SUM(opening_inventory + closing_inventory) AS store_open_close_sum, CASE WHEN SUM(opening_inventory + closing_inventory) > 0 THEN ROUND( SUM(sales_qty) / (SUM(opening_inventory + closing_inventory) / 2.0), 2 ) ELSE 0 END AS store_avg_str FROM filtered GROUP BY cluster, branch_code, marketplace_mapped ), cluster_avg AS ( SELECT cluster, SUM(sales_qty) AS cluster_sales, SUM(opening_inventory + closing_inventory) AS cluster_open_close_sum, CASE WHEN SUM(opening_inventory + closing_inventory) > 0 THEN ROUND( SUM(sales_qty) / (SUM(opening_inventory + closing_inventory) / 2.0), 2 ) ELSE 0 END AS cluster_avg_str FROM filtered GROUP BY cluster ), cluster_sku AS ( SELECT cluster, sku_group, SUM(sales_qty) AS sku_cluster_sales, SUM(opening_inventory + closing_inventory) AS sku_cluster_open_close_sum, CASE WHEN SUM(opening_inventory + closing_inventory) > 0 THEN ROUND( SUM(sales_qty) / (SUM(opening_inventory + closing_inventory) / 2.0), 2 ) ELSE 0 END AS sku_cluster_sell_through FROM filtered GROUP BY cluster, sku_group ) SELECT ss.cluster, ss.branch_code, ss.marketplace_mapped, ss.sku_group, ss.new_category, CASE WHEN ss.new_category = \'T-Shirts\' THEN CASE WHEN UPPER(TRIM(ss.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(ss.designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(ss.designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(ss.designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(ss.designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(ss.designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(ss.designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(ss.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(ss.designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(ss.designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(ss.designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(ss.designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' ELSE \'Others\' END WHEN ss.new_category = \'Shirts\' THEN CASE WHEN UPPER(TRIM(ss.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(ss.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(ss.designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(ss.designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'PRINTED\' THEN \'Printed\' WHEN UPPER(TRIM(ss.designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(ss.designs)) = \'FLORAL\' THEN \'Printed\' WHEN UPPER(TRIM(ss.designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(ss.designs)) = \'GEOMETRIC\' THEN \'Printed\' WHEN UPPER(TRIM(ss.designs)) = \'TIE & DYE\' THEN \'Printed\' WHEN UPPER(TRIM(ss.designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(ss.designs)) = \'GRAPHIC PRINT\' THEN \'Printed\' WHEN UPPER(TRIM(ss.designs)) = \'ANIMAL PRINT\' THEN \'Printed\' ELSE \'Other\' END ELSE ss.designs END AS designs, CASE WHEN ss.new_category = \'T-Shirts\' THEN CASE WHEN TRIM(LOWER(ss.collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(ss.collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(ss.collar_new)) = \'polo\' THEN \'Polo\' ELSE ss.collar_new END ELSE ss.collar_new END AS collar_new, ss.sleeve_type, ss.fit, ss.style, ss.cut_size_with_jit_flag, ss.jit_qty, ss.num_size_available, ss.fresh_inventory, ss.opening_inventory, ss.closing_inventory, ss.sales_qty, ss.outwards, ss.sell_through_1, ss.sell_through_2, cs.sku_cluster_sell_through, sa.store_avg_str, ca.cluster_avg_str, CASE WHEN ss.sell_through_1 > sa.store_avg_str THEN \'High\' ELSE \'Low\' END AS store_perf_flag, CASE WHEN cs.sku_cluster_sell_through > ca.cluster_avg_str THEN \'High\' ELSE \'Low\' END AS cluster_perf_flag FROM sku_store ss LEFT JOIN store_avg sa ON ss.cluster = sa.cluster AND ss.branch_code = sa.branch_code AND ss.marketplace_mapped = sa.marketplace_mapped LEFT JOIN cluster_avg ca ON ss.cluster = ca.cluster LEFT JOIN cluster_sku cs ON ss.cluster = cs.cluster AND ss.sku_group = cs.sku_group WHERE ss.cluster IS NOT NULL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
